  function ottoviasTollActionLabel(toll){if(!toll)return'Ação';if(Date.now()<Number(toll.openUntil||0))return'Passar';if(toll.paymentPending)return'Levantar';return'Pagar';}
  function ottoviasTollContextLabel(toll){if(!toll)return'Pedágio OTTOVIAS';if(Date.now()<Number(toll.openUntil||0))return`${toll.name} • cancela aberta`;if(toll.paymentPending)return`${toll.name} • levante a cancela`;return`${toll.name} • pedágio ${Number(toll.cost||5)} moedas`;}
