  function michelleBiomeLabel(biome){return({city:'Travessia Urbana',desert:'Trecho Deserto',field:'Trecho Campo',snow:'Trecho Neve',beach:'Trecho Praia',country:'Trecho Rural'})[biome]||'rede viária do OTTHI World';}
