  function michelleAddNews(type,title,body,key='',level='info',announce=false){const data=ensureOttoviasState(),dedupe=String(key||`${type}:${title}:${body}`);if(data.news.some(item=>item.key===dedupe))return false;const item={id:`michelle-${++data.newsSeq}`,key:dedupe,type,title,body,level,at:Date.now()};data.news.unshift(item);data.news=data.news.slice(0,OTTOVIAS_NEWS_LIMIT);data.lastBulletinAt=item.at;saveState();if(announce&&michelleShouldBroadcast(level,type))toast(`📡 Michelle informa: ${title}`,(level==='alert'||level==='attention')?'warn':'good',2600);return item;}
