  window.OTTHI_OTTOVIAS={initialize:createOttoviasWorld,update:updateOttoviasHighway,openCommunication:openMichelleOttovias,openNews:openOttoviasNews,startTour:startOttoviasTour,cancelTour:cancelOttoviasTour,startCommunication:startOttoviasCommunicationMission,cancelCommunication:cancelOttoviasCommunicationMission,state:()=>ensureOttoviasState(),nearest:ottoviasNearestInfo,routes:ottoviasRoutes,liveReport:michelleCurrentReport,news:()=>ensureOttoviasState().news.map(item=>({...item})),askMichelle:michelleAnswer};
